// Hand-written. Not generated by Speakeasy.
package provider

import (
	"testing"

	tfTypes "github.com/authlete/terraform-provider-authlete/v3/internal/provider/types"
	"github.com/hashicorp/terraform-plugin-framework/types"
)

func strs(vals ...string) []types.String {
	out := make([]types.String, 0, len(vals))
	for _, v := range vals {
		out = append(out, types.StringValue(v))
	}
	return out
}

func joined(vals []types.String) string {
	s := ""
	for i, v := range vals {
		if i > 0 {
			s += ","
		}
		switch {
		case v.IsNull():
			s += "<null>"
		case v.IsUnknown():
			s += "<unknown>"
		default:
			s += v.ValueString()
		}
	}
	return s
}

func TestKeepOrder(t *testing.T) {
	for _, tc := range []struct {
		name string
		prev []types.String
		next []types.String
		want string
	}{
		{
			name: "reordered keeps the stored order",
			prev: strs("REFRESH_TOKEN", "CLIENT_CREDENTIALS", "AUTHORIZATION_CODE"),
			next: strs("AUTHORIZATION_CODE", "CLIENT_CREDENTIALS", "REFRESH_TOKEN"),
			want: "REFRESH_TOKEN,CLIENT_CREDENTIALS,AUTHORIZATION_CODE",
		},
		{
			name: "identical is left alone",
			prev: strs("CODE", "ID_TOKEN"),
			next: strs("CODE", "ID_TOKEN"),
			want: "CODE,ID_TOKEN",
		},
		{
			name: "an added element is a real change",
			prev: strs("CODE"),
			next: strs("CODE", "ID_TOKEN"),
			want: "CODE,ID_TOKEN",
		},
		{
			name: "a removed element is a real change",
			prev: strs("CODE", "ID_TOKEN"),
			next: strs("CODE"),
			want: "CODE",
		},
		{
			name: "a replaced element is a real change even at the same length",
			prev: strs("CODE", "ID_TOKEN"),
			next: strs("CODE", "TOKEN"),
			want: "CODE,TOKEN",
		},
		{
			name: "a reorder that also edits is a real change",
			prev: strs("A", "B", "C"),
			next: strs("C", "B", "D"),
			want: "C,B,D",
		},
		{
			name: "duplicates are counted, not deduplicated",
			prev: strs("A", "A", "B"),
			next: strs("A", "B", "B"),
			want: "A,B,B",
		},
		{
			name: "no prior state takes what the API returned",
			prev: nil,
			next: strs("CODE"),
			want: "CODE",
		},
		{
			name: "both empty stays empty, not null",
			prev: []types.String{},
			next: []types.String{},
			want: "",
		},
		{
			name: "an unknown element is not comparable, so the API wins",
			prev: []types.String{types.StringUnknown()},
			next: strs("CODE"),
			want: "CODE",
		},
		{
			name: "a null element is not comparable either",
			prev: []types.String{types.StringNull()},
			next: strs("CODE"),
			want: "CODE",
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if got := joined(keepOrder(tc.prev, tc.next)); got != tc.want {
				t.Errorf("keepOrder(%s, %s) = %s, want %s",
					joined(tc.prev), joined(tc.next), got, tc.want)
			}
		})
	}
}

// TestKeepOrderDoesNotAliasTheAPIValue checks that a held value is the stored
// slice rather than the refreshed one, since the point is to discard what the
// API returned.
func TestKeepServiceListOrderHoldsEveryReorderedList(t *testing.T) {
	prev := &ServiceResourceModel{
		SupportedAttachments:      strs("EXTERNAL", "EMBEDDED"),
		SupportedClaimTypes:       strs("DISTRIBUTED", "NORMAL"),
		SupportedClaims:           strs("sub", "email", "name"),
		SupportedDisplays:         strs("POPUP", "PAGE"),
		SupportedGrantTypes:       strs("REFRESH_TOKEN", "AUTHORIZATION_CODE"),
		SupportedPromptValues:     strs("CONSENT", "LOGIN"),
		SupportedResponseTypes:    strs("ID_TOKEN", "CODE"),
		SupportedServiceProfiles:  strs("OPEN_BANKING", "FAPI"),
		SupportedTokenAuthMethods: strs("PRIVATE_KEY_JWT", "NONE"),
	}
	cur := &ServiceResourceModel{
		SupportedAttachments:      strs("EMBEDDED", "EXTERNAL"),
		SupportedClaimTypes:       strs("NORMAL", "DISTRIBUTED"),
		SupportedClaims:           strs("name", "sub", "email"),
		SupportedDisplays:         strs("PAGE", "POPUP"),
		SupportedGrantTypes:       strs("AUTHORIZATION_CODE", "REFRESH_TOKEN"),
		SupportedPromptValues:     strs("LOGIN", "CONSENT"),
		SupportedResponseTypes:    strs("CODE", "ID_TOKEN"),
		SupportedServiceProfiles:  strs("FAPI", "OPEN_BANKING"),
		SupportedTokenAuthMethods: strs("NONE", "PRIVATE_KEY_JWT"),
	}

	keepServiceListOrder(prev, cur)

	for name, got := range map[string][2][]types.String{
		"supported_attachments":        {prev.SupportedAttachments, cur.SupportedAttachments},
		"supported_claim_types":        {prev.SupportedClaimTypes, cur.SupportedClaimTypes},
		"supported_claims":             {prev.SupportedClaims, cur.SupportedClaims},
		"supported_displays":           {prev.SupportedDisplays, cur.SupportedDisplays},
		"supported_grant_types":        {prev.SupportedGrantTypes, cur.SupportedGrantTypes},
		"supported_prompt_values":      {prev.SupportedPromptValues, cur.SupportedPromptValues},
		"supported_response_types":     {prev.SupportedResponseTypes, cur.SupportedResponseTypes},
		"supported_service_profiles":   {prev.SupportedServiceProfiles, cur.SupportedServiceProfiles},
		"supported_token_auth_methods": {prev.SupportedTokenAuthMethods, cur.SupportedTokenAuthMethods},
	} {
		if joined(got[0]) != joined(got[1]) {
			t.Errorf("%s: kept %s, want the stored order %s", name, joined(got[1]), joined(got[0]))
		}
	}
}

func TestKeepClientListOrderHoldsEveryReorderedList(t *testing.T) {
	prev := &ClientResourceModel{
		GrantTypes:    strs("REFRESH_TOKEN", "AUTHORIZATION_CODE"),
		ResponseModes: strs("FORM_POST", "QUERY"),
		ResponseTypes: strs("ID_TOKEN", "CODE"),
		Extension:     &tfTypes.ClientExtension{RequestableScopes: strs("read", "write")},
	}
	cur := &ClientResourceModel{
		GrantTypes:    strs("AUTHORIZATION_CODE", "REFRESH_TOKEN"),
		ResponseModes: strs("QUERY", "FORM_POST"),
		ResponseTypes: strs("CODE", "ID_TOKEN"),
		Extension:     &tfTypes.ClientExtension{RequestableScopes: strs("write", "read")},
	}

	keepClientListOrder(prev, cur)

	if joined(cur.GrantTypes) != "REFRESH_TOKEN,AUTHORIZATION_CODE" {
		t.Errorf("grant_types: %s", joined(cur.GrantTypes))
	}
	if joined(cur.ResponseModes) != "FORM_POST,QUERY" {
		t.Errorf("response_modes: %s", joined(cur.ResponseModes))
	}
	if joined(cur.ResponseTypes) != "ID_TOKEN,CODE" {
		t.Errorf("response_types: %s", joined(cur.ResponseTypes))
	}
	if joined(cur.Extension.RequestableScopes) != "read,write" {
		t.Errorf("requestable_scopes: %s", joined(cur.Extension.RequestableScopes))
	}
}

// The extension object is a pointer and Authlete does not always return one,
// so the nil cases have to be safe. A client whose extension appears or
// disappears between reads must not panic, and must not be given an order
// from the other side.
func TestKeepClientListOrderToleratesAMissingExtension(t *testing.T) {
	for name, tc := range map[string]struct {
		prev, cur *tfTypes.ClientExtension
		want      string
	}{
		"both absent": {nil, nil, ""},
		"absent in state, present in the response": {
			nil, &tfTypes.ClientExtension{RequestableScopes: strs("write", "read")}, "write,read",
		},
		"present in state, absent from the response": {
			&tfTypes.ClientExtension{RequestableScopes: strs("read", "write")}, nil, "",
		},
		"a real edit is not held back": {
			&tfTypes.ClientExtension{RequestableScopes: strs("read", "write")},
			&tfTypes.ClientExtension{RequestableScopes: strs("read")}, "read",
		},
	} {
		t.Run(name, func(t *testing.T) {
			prev := &ClientResourceModel{Extension: tc.prev}
			cur := &ClientResourceModel{Extension: tc.cur}

			keepClientListOrder(prev, cur)

			got := ""
			if cur.Extension != nil {
				got = joined(cur.Extension.RequestableScopes)
			}
			if got != tc.want {
				t.Errorf("requestable_scopes = %q, want %q", got, tc.want)
			}
		})
	}
}
